package com.robot.platform.ai.digitalhuman;import com.robot.platform.ai.digitalhuman.realtime.DigitalHumanStateMapper;import com.robot.platform.ai.realtime.protocol.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DigitalHumanStateEventTest {@Test void mapsAudioToolInterruptStates(){assertEquals("SPEAKING",DigitalHumanStateMapper.stateFor(new RealtimeServerEvent.AssistantAudioStartedEvent("s","t",new RealtimeAudioFormat("PCM",24000,1))));assertEquals("EXECUTING",DigitalHumanStateMapper.stateFor(new RealtimeServerEvent.ToolStartedEvent("s","t","c","nav")));assertEquals("IDLE",DigitalHumanStateMapper.stateFor(new RealtimeServerEvent.PlaybackStopEvent("s","t","barge-in")));}}
